pub fn next_delay(attempt: u32, config: &RetryConfig) -> u64 {
    let shift = attempt.saturating_sub(1);
    let multiplier = 1u64.checked_shl(shift).unwrap_or(u64::MAX);
    config
        .base_delay_ms
        .saturating_mul(multiplier)
        .min(config.max_delay_ms)
}

